"use strict";

/** TEST GRADE: unit */

/**
 * Regression check for canonical DP stateful exact-cache removal.
 *
 * Ensures:
 * 1. Two states A and B with identical buildStateKey(state) but differing route accounting
 *    (decisionDepth, rawRouteLength, autoStepCount, autoPickupCount, autoBattleCount)
 *    do not cross-contaminate action expansion.
 * 2. When A is enumerated first (simulating cache warm), successor states generated by
 *    applying actions to B strictly inherit B's accounting metadata plus the exact
 *    action/auto increment, without reverting to A.
 * 3. Covers at least one battle/pickup action with travelState and one changeFloor.
 * 4. Verifies a 100-expansion search maintains exact consistency with expected
 *    expansion, generated/registered/frontier counts, best progress state key & accounting,
 *    and exact-cache sizes == 0 while skeleton cache and battle estimate cache are active.
 */

const assert = require("node:assert");
const { loadProject } = require("./lib/project-loader");
const { FunctionBackedBattleResolver } = require("./lib/battle-resolver");
const { StaticSimulator } = require("./lib/simulator");
const { searchDP } = require("./lib/dp-search");
const { createNoStateChangeChoiceResolver } = require("./lib/onlyup-mt1-real-route-gate");
const { buildStateKey } = require("./lib/state-key");
const { cloneState, ensureMeta, getDecisionDepth, getRawRouteLength } = require("./lib/state");

function checkStatefulExactCacheRegression() {
  const project = loadProject("Only upV2.1/Only upV2.1");
  const choiceResolver = createNoStateChangeChoiceResolver();
  const simulator = new StaticSimulator(project, {
    stopFloorId: "MT6",
    battleResolver: new FunctionBackedBattleResolver(project),
    searchGraphMode: "primitive",
    enableFightToLevelUp: false,
    enableResourcePocket: false,
    enableResourceCluster: false,
    enableResourceChain: false,
    autoPickupEnabled: true,
    autoBattleEnabled: true,
    choiceResolver,
  });

  const stateA = simulator.createInitialState();
  const stateB = cloneState(stateA);

  // Artificially change B's accounting metadata
  ensureMeta(stateA);
  stateA.meta.decisionDepth = 0;
  stateA.meta.rawRouteLength = 4;
  stateA.meta.autoStepCount = 4;
  stateA.meta.autoPickupCount = 3;
  stateA.meta.autoBattleCount = 1;

  ensureMeta(stateB);
  stateB.meta.decisionDepth = 10;
  stateB.meta.rawRouteLength = 50;
  stateB.meta.autoStepCount = 40;
  stateB.meta.autoPickupCount = 28;
  stateB.meta.autoBattleCount = 12;

  assert.strictEqual(
    buildStateKey(stateA),
    buildStateKey(stateB),
    "State A and State B must have identical buildStateKey",
  );
  assert.notStrictEqual(getDecisionDepth(stateA), getDecisionDepth(stateB));
  assert.notStrictEqual(getRawRouteLength(stateA), getRawRouteLength(stateB));

  // Step 1: Enumerate stateA (in old implementation, this cached actions with stateA travelState/accounting)
  const actionsA = simulator.enumerateActions(stateA);
  assert.ok(actionsA.length > 0, "stateA should have actions");

  // Step 2: Enumerate stateB
  const actionsB = simulator.enumerateActions(stateB);
  assert.ok(actionsB.length > 0, "stateB should have actions");

  // Find a battle or pickup action (carrying travelState) and a changeFloor action
  const battleOrPickup = actionsB.find((a) => a.kind === "battle" || a.kind === "pickup");
  assert.ok(battleOrPickup, "must find a battle or pickup action");
  assert.ok(battleOrPickup.travelState, "battle/pickup action must carry travelState");

  const succB_battle = simulator.applyAction(stateB, battleOrPickup);
  assert.ok(succB_battle, "applying battle/pickup on B must succeed");
  assert.strictEqual(
    succB_battle.meta.decisionDepth,
    stateB.meta.decisionDepth + 1,
    "successor of B must inherit B's decisionDepth + 1",
  );
  assert.ok(
    succB_battle.meta.rawRouteLength > stateB.meta.rawRouteLength,
    "successor of B must strictly increase B's rawRouteLength",
  );
  assert.ok(
    succB_battle.meta.rawRouteLength > 50,
    `successor rawRouteLength must be > 50, got ${succB_battle.meta.rawRouteLength}`,
  );

  // Test changeFloor
  // Apply the 9 battle actions leading to changeFloor@MT1:6,0
  let curA = stateA;
  let curB = stateB;
  const decisions = [
    'battle:blackSlime@MT1:8,7',
    'battle:redSlime@MT1:9,6',
    'battle:slimelord@MT1:9,4',
    'battle:slimelord@MT1:3,4',
    'battle:skeletonWarrior@MT1:2,1',
    'battle:vampire@MT1:4,3',
    'battle:skeletonCaptain@MT1:8,3',
    'battle:skeletonCaptain@MT1:2,5',
    'battle:skeleton@MT1:4,1',
  ];

  for (const summary of decisions) {
    const actA = simulator.enumerateActions(curA).find((a) => a.summary === summary);
    assert.ok(actA, `action ${summary} must exist for curA`);
    curA = simulator.applyAction(curA, actA);

    const actB = simulator.enumerateActions(curB).find((a) => a.summary === summary);
    assert.ok(actB, `action ${summary} must exist for curB`);
    curB = simulator.applyAction(curB, actB);
  }

  assert.strictEqual(
    buildStateKey(curA),
    buildStateKey(curB),
    "curA and curB must have identical buildStateKey before changeFloor",
  );
  assert.notStrictEqual(getDecisionDepth(curA), getDecisionDepth(curB));
  assert.notStrictEqual(getRawRouteLength(curA), getRawRouteLength(curB));

  // Enumerate curA first (warm cache in buggy versions)
  const actsA = simulator.enumerateActions(curA);
  const cfA = actsA.find((a) => a.kind === "changeFloor");
  assert.ok(cfA, "changeFloor action must exist for curA");

  // Enumerate curB next
  const actsB = simulator.enumerateActions(curB);
  const cfB = actsB.find((a) => a.kind === "changeFloor");
  assert.ok(cfB, "changeFloor action must exist for curB");

  const succB_floor = simulator.applyAction(curB, cfB);
  assert.ok(succB_floor, "changeFloor application on curB must succeed");
  assert.strictEqual(
    succB_floor.meta.decisionDepth,
    curB.meta.decisionDepth + 1,
    "changeFloor successor must inherit B's decisionDepth + 1",
  );
  assert.ok(
    succB_floor.meta.rawRouteLength > curB.meta.rawRouteLength,
    "changeFloor successor must increase B's rawRouteLength",
  );
  assert.strictEqual(
    succB_floor.meta.decisionDepth,
    stateB.meta.decisionDepth + 10,
    "total decision depth on B branch must be stateB.decisionDepth + 10",
  );
}

