function checkHundredExpansionSearchConsistency() {
  const project = loadProject("Only upV2.1/Only upV2.1");
  const choiceResolver1 = createNoStateChangeChoiceResolver();
  const choiceResolver2 = createNoStateChangeChoiceResolver();

  const createSim = (choiceResolver) => new StaticSimulator(project, {
    stopFloorId: "MT6",
    battleResolver: new FunctionBackedBattleResolver(project),
    searchGraphMode: "primitive",
    enableFightToLevelUp: false,
    enableResourcePocket: false,
    enableResourceCluster: false,
    enableResourceChain: false,
    autoPickupEnabled: true,
    autoBattleEnabled: true,
    choiceResolver,
  });

  const sim1 = createSim(choiceResolver1);
  const sim2 = createSim(choiceResolver2);

  const res1 = searchDP(sim1, sim1.createInitialState(), {
    maxExpansions: 100,
    stopFloorId: "MT6",
    targetFloorId: "MT6",
  });

  const res2 = searchDP(sim2, sim2.createInitialState(), {
    maxExpansions: 100,
    stopFloorId: "MT6",
    targetFloorId: "MT6",
  });

  // Lock exact consistency against frozen baseline
  assert.strictEqual(res1.expansions, 100, "must expand exactly 100 states");
  assert.strictEqual(res2.expansions, 100, "must expand exactly 100 states");
  assert.strictEqual(res1.frontierSize, EXPECTED_FRONTIER_SIZE, `frontierSize must be ${EXPECTED_FRONTIER_SIZE}`);
  assert.strictEqual(res2.frontierSize, EXPECTED_FRONTIER_SIZE, `frontierSize must be ${EXPECTED_FRONTIER_SIZE}`);
  assert.strictEqual(res1.stoppedReason, EXPECTED_STOPPED_REASON, "stoppedReason must match expected");
  assert.strictEqual(res2.stoppedReason, EXPECTED_STOPPED_REASON, "stoppedReason must match expected");
  assert.strictEqual(res1.diagnostics.registered, EXPECTED_REGISTERED, `registered states must be ${EXPECTED_REGISTERED}`);
  assert.strictEqual(res2.diagnostics.registered, EXPECTED_REGISTERED, `registered states must be ${EXPECTED_REGISTERED}`);
  assert.strictEqual(res1.diagnostics.generated, EXPECTED_GENERATED, `generated states must be ${EXPECTED_GENERATED}`);
  assert.strictEqual(res2.diagnostics.generated, EXPECTED_GENERATED, `generated states must be ${EXPECTED_GENERATED}`);

  assert.strictEqual(buildStateKey(res1.bestProgressState), EXPECTED_BEST_PROGRESS_KEY, "bestProgress exact stateKey must match frozen contract");
  assert.strictEqual(buildStateKey(res2.bestProgressState), EXPECTED_BEST_PROGRESS_KEY, "bestProgress exact stateKey must match frozen contract");
  assert.strictEqual(buildStateKey(res1.bestProgressState), buildStateKey(res2.bestProgressState));
  assert.deepStrictEqual(res1.bestProgressState.meta, res2.bestProgressState.meta);

  const stats = sim1.getActionExpansionCacheStats();

  // Exact caches must have size == 0, hits == 0, stores == 0
  assert.strictEqual(stats.reachability.size, 0, "reachability cache size must be 0");
  assert.strictEqual(stats.reachability.hits, 0, "reachability hits must be 0");
  assert.strictEqual(stats.reachability.stores, 0, "reachability stores must be 0");

  assert.strictEqual(stats.primitiveActions.size, 0, "primitiveActions cache size must be 0");
  assert.strictEqual(stats.primitiveActions.hits, 0, "primitiveActions hits must be 0");
  assert.strictEqual(stats.primitiveActions.stores, 0, "primitiveActions stores must be 0");

  // Skeleton cache must have real hits and non-zero size
  assert.ok(stats.reachabilitySkeleton.hits > 0, "reachabilitySkeleton must have real hits");
  assert.ok(stats.reachabilitySkeleton.size > 0, "reachabilitySkeleton size must be > 0");

  // Battle estimate cache must be preserved and have hits
  assert.ok(stats.battleResolver, "battleResolver cache stats must exist");
  assert.ok(stats.battleResolver.battleEstimate.hits > 0, "battleEstimate must have real hits");
  assert.ok(stats.battleResolver.battleEstimate.size > 0, "battleEstimate size must be > 0");

  // Best progress state verification
  assert.ok(res1.bestProgressState, "bestProgressState must exist");
  assert.strictEqual(res1.bestProgressState.floorId, "MT2");
  assert.strictEqual(getDecisionDepth(res1.bestProgressState), 11);
  assert.strictEqual(getRawRouteLength(res1.bestProgressState), 53);
  assert.strictEqual(res1.bestProgressState.meta.autoStepCount, 42);
  assert.strictEqual(res1.bestProgressState.meta.autoPickupCount, 30);
  assert.strictEqual(res1.bestProgressState.meta.autoBattleCount, 12);
}

function main() {
  checkStatefulExactCacheRegression();
  checkHundredExpansionSearchConsistency();
  console.log("check-action-expansion-cache-correctness: ok");
}

if (require.main === module) main();

module.exports = {
  main,
  checkStatefulExactCacheRegression,
  checkHundredExpansionSearchConsistency,
};
